      for (const runId of new Set(generatedViews.map(view => view.generation!.runId))) {
        // Chat lifecycle records win; migration must never overwrite their pinned source or prompt text.
        if (await this.store.read(legacyEvalRunId(runId))) continue;
        // The chat observer owns active generations, including the interval before its first save.
        if (generatedViews.some(view => view.generation!.runId === runId && ['queued', 'generating'].includes(view.generation!.status))) continue;
        const children = generatedViews.filter(view => view.generation!.runId === runId).map(view => ({
          id: view.generation!.chatId, title: view.name,
          generation: { metadata: view.generation!, viewId: view.id, parentViewId: view.parentViewId ?? '', source: { documentId, workspaceInstanceId: 'migration' },
            ...(view.finalCheckpointId ? { history: { ...structuredClone(history), headId: view.finalCheckpointId, baselineId: view.forkCheckpointId ?? view.startCheckpointId } } : {}) }
        } as import('../../../domain/mapping/agent-chat/agentChat').ChatSession));
        await this.recordLegacy(children, undefined, true);
        migrated += children.filter(child => child.generation!.metadata.status === 'finished' && child.generation!.history && !existing.has(`legacy:${documentId}:${child.generation!.viewId}`)).length;
      }
      for (const view of Object.values(history.canvasViews?.saved ?? {})) {
        const key = `legacy:${documentId}:${view.id}`;
        if (view.generation) continue;
        if (!view.alternativeGroupId || view.archivedAt || !view.finalCheckpointId || existing.has(key)) continue;
        const group = view.alternativeGroupId;
        const hex = sha256(`${documentId}:${group}`).slice(0, 32);
        const requestId = `${hex.slice(0,8)}-${hex.slice(8,12)}-4${hex.slice(13,16)}-8${hex.slice(17,20)}-${hex.slice(20)}`;
        const contextName = `Migrated generation · ${metadata.name}`.slice(0,120);
        const { agentContextId } = await this.contexts.create({ requestId, name: contextName,
          context: JSON.stringify({ sourceDocumentId: documentId, generationRunId: group }) });
        const copy = copyCompareHistory(history, view.finalCheckpointId), document = documentFromHistory(copy);
        await this.projects.projectCatalogs.saveMappingDiagram(index.projectId, { name: view.name.slice(0, 120), type: 'generated', history: copy, scene: document.scene, edges: document.edges,
          repositoryId: metadata.repositoryId ?? (project?.repositories?.length === 1 ? project.repositories[0].id : undefined),
          generated: { key, agentContextId, contextName, stage: 'legacy', source: { documentId, viewId: view.id, checkpointId: view.finalCheckpointId }, generation: view.generation } });
        migrated++;
      }
    }
    return { migrated };
  }
  /** Archives a generated canvas, like deleting it in Mapping. */
  async deleteCanvas(id: string) {
    if (!(await this.canvases.list()).some(canvas => canvas.id === id)) throw new ApplicationError('invalid-input', 'Generated canvas not found.');
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Open a project first.');
    await this.projects.projectCatalogs.archiveRepresentation(project.id, id, { includeHistory: false });
  }
  /** Cancels the run if needed, archives its canvases and removes the record, along with its reruns. */
  async deleteRun(id: string) {
    await this.read(id);
    for (const rerun of await this.store.list()) if (!rerun.deletedAt && rerun.parentRunId === id) await this.deleteRun(rerun.id);
    await this.deleteSingleRun(id);
  }
  /** Deletes exactly the selected runs; reruns in other navigation groups are kept. */
  async deleteRuns(ids: string[]) {
    const selected = new Set(ids);
    for (const run of await this.list()) if (selected.has(run.id)) await this.deleteSingleRun(run.id);
  }
  private async deleteSingleRun(id: string) {
    const run = await this.read(id);
    this.deleted.add(id);
    if (run.compatibility && this.cancelLegacy) await Promise.all(run.compatibility.candidates.map(c => this.cancelLegacy!(c.chatId)));
    this.running.get(id)?.abort();
    await this.legacyGenerations.drain();
    await this.saves.get(id);
    const live = new Set((await this.canvases.list()).map(canvas => canvas.id));
    for (const cell of run.cells) if (cell.canvasId && live.has(cell.canvasId)) await this.deleteCanvas(cell.canvasId);
    await this.store.save({ ...run, deletedAt: new Date().toISOString() });
    if (run.legacy) await this.legacy?.delete(id).catch(() => {});
  }
  /** Removes everything one workflow generated from an AgentContext. The context itself is kept. */
  async deleteContextOutputs(agentContextId: string, workflow: EvalWorkflowId) {
    await this.deleteContextComparisons?.(agentContextId, workflow);
    await this.deleteRuns((await this.list()).filter(run => run.agentContextId === agentContextId && run.workflow === workflow).map(run => run.id));
    for (const canvas of await this.canvases.list())
      if (canvas.generated?.agentContextId === agentContextId && generatedWorkflow(canvas.generated) === workflow) await this.deleteCanvas(canvas.id);
    for (const session of await this.comparisons.list())
      if ((await this.comparisons.read(session.id)).canvases.every(copy => copy.generated?.agentContextId === agentContextId && generatedWorkflow(copy.generated) === workflow)) await this.comparisons.delete(session.id);
  }
  dispose() { for (const abort of this.running.values()) abort.abort(); this.runtime.dispose?.(); }
}

import { defaultPromptTemplateBase, legacyPromptTemplateBase, parsePromptSections } from '../../../domain/mapping/evals/promptTemplateBase';
import type { PromptProjectSnapshot } from '../../../domain/mapping/evals/evalPrompt';
import { randomUUID } from 'node:crypto';
import { ApplicationError } from '../../core/errors';
import { sha256 } from '../../../domain/core/sha256';
import { evalWorkflowIds, evalWorkflows, templateAlternativePrompt, promptHasErrors, validatePromptStages, type EvalWorkflowId } from '../../../domain/mapping/evals/evalWorkflows';
import { latestVersion, saveEvalPromptSchema, trackPromptLineageSchema, type PromptDerivation, type PromptVersionRef, type EvalPrompt } from '../../../domain/mapping/evals/evalPrompt';
import type { EvalRunPrompt } from '../../../domain/mapping/evals/evalRun';
import { templateReferences } from '../../../domain/mapping/evals/promptTemplate';
import type { EvalReferenceService } from './evalReferenceService';

export interface EvalPromptStore { list(): Promise<EvalPrompt[]>; read(id: string): Promise<EvalPrompt | null>; save(prompt: EvalPrompt): Promise<void> }

export const promptContentHash = (stages: Record<string, string>) => sha256(JSON.stringify(Object.fromEntries(Object.entries(stages).sort(([a], [b]) => a.localeCompare(b)))));

export class EvalPromptService {
  private writes: Promise<unknown> = Promise.resolve();
  private serialize<T>(work: () => Promise<T>): Promise<T> {
    const pending = this.writes.then(work); this.writes = pending.catch(() => {}); return pending;
  }
  private async validateDerivation(derivation: PromptDerivation, workflow: EvalWorkflowId, target?: PromptVersionRef) {
    const visit = async (ref: PromptVersionRef, path: Set<string>): Promise<void> => {
      const key = `${ref.promptId}:${ref.version}`;
      if (path.has(key)) throw new ApplicationError('invalid-input', 'Prompt lineage cannot contain a cycle.');
      const prompt = await this.read(ref.promptId), version = prompt.versions.find(v => v.version === ref.version);
      const historyAdaptation = workflow === 'diagram-history' && prompt.workflow === 'diagram-change-proposal';
      if ((!historyAdaptation && prompt.workflow !== workflow) || !version) throw new ApplicationError('invalid-input', 'Parent must be an existing version in the same workflow (diagram histories may derive from diagram-change proposals).');
      const next = new Set(path); next.add(key);
      for (const parent of version.parents?.length ? version.parents : version.derivation ? [version.derivation.parent] : []) await visit(parent, next);
    };
    await visit(derivation.parent, new Set(target ? [`${target.promptId}:${target.version}`] : []));
  }

  /** One-time provenance backfill for legacy records. Text and version identities never change. */
  trackLineage(id: string, raw: unknown) {
    const input = trackPromptLineageSchema.parse(raw);
    return this.serialize(async () => {
      const prompt = await this.read(id), version = prompt.versions.find(v => v.version === input.version);
      if (!version || promptContentHash(version.stages) !== input.expectedContentHash) throw new ApplicationError('conflict', 'Prompt version text does not match the migration.');
      if (version.derivation) {
        if (JSON.stringify(version.derivation) !== JSON.stringify(input.derivation)) throw new ApplicationError('conflict', 'This version already has immutable lineage.');
        return prompt;
      }
      await this.validateDerivation(input.derivation, prompt.workflow, { promptId: id, version: input.version });
      const now = new Date().toISOString();
      const next = { ...prompt, updatedAt: now, versions: prompt.versions.map(v => v.version === input.version ? { ...v, contentHash: input.expectedContentHash, derivation: input.derivation, lineageRecordedAt: now } : v) };
      await this.store.save(next); return next;
    });
  }
  /** A separate, immutable prompt copy for a relaunch; deterministic identity makes retries safe. */
  forkForAttempt(requestId: string, workflow: EvalWorkflowId, source: EvalRunPrompt, stages: Record<string, string>) {
    return this.serialize(async () => {
    const id = `attempt-${requestId}`, projectId = await this.projectId();
    const existing = await this.store.read(id);
    if (existing) {
      if (existing.projectId !== projectId || existing.workflow !== workflow || JSON.stringify(existing.versions[0].stages) !== JSON.stringify(stages)
        || (existing.versions[0].derivation && JSON.stringify(existing.versions[0].derivation.parent) !== JSON.stringify({ promptId: source.promptId, version: source.version })))
        throw new ApplicationError('conflict', 'Relaunch request ID already used for a different prompt.');
      return existing;
    }
    const derivation: PromptDerivation | undefined = source.version ? { parent: { promptId: source.promptId, version: source.version }, kind: 'relaunch' } : undefined;
    if (derivation) await this.validateDerivation(derivation, workflow);
    const templateBase = source.templateBase ?? legacyPromptTemplateBase(stages);
    const issues = Object.values(stages).flatMap(text => parsePromptSections(text, templateBase).issues);
    if (issues.length) throw new ApplicationError('invalid-input', issues.map(i => i.message).join(' '));
    const now = new Date().toISOString();
    const fork: EvalPrompt = { schemaVersion: 1, id, projectId, workflow, name: `${source.name} · edited attempt`.slice(0, 120), createdAt: now, updatedAt: now,
      versions: [{ version: 1, templateBase: source.templateBase ?? legacyPromptTemplateBase(stages), parents: source.version ? [{ promptId: source.promptId, version: source.version, relation: 'relaunch' }] : [], format: 'explicit-v1', createdAt: now, note: `Relaunched from ${source.promptId} v${source.version ?? 'unknown'}.`, contentHash: promptContentHash(stages), ...(derivation ? { derivation } : {}), stages }] };
    await this.store.save(fork); return fork;
    });
  }
  /** Retry state for in-flight saves; like other request IDs it does not survive restarts. */
  private saves = new Map<string, { hash: string; result: Promise<EvalPrompt> }>();
  private seeding?: Promise<void>;
  constructor(private store: EvalPromptStore, private projects: { loadProject(): Promise<{ id: string } | null> },
    readonly references?: Pick<EvalReferenceService, 'ids' | 'read'> & Partial<Pick<EvalReferenceService, 'create'>>,
    private snapshots?: { save(value: PromptProjectSnapshot): Promise<void>; read(id: string): Promise<PromptProjectSnapshot | null>; list(): Promise<PromptProjectSnapshot[]> }) {}
  private async projectId() {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Open a project first.');
    return project.id;
  }
  /** Each workflow starts with its original built-in prompt as v1. */
  private async seed(projectId: string) {
    const existing = await this.store.list(), now = new Date().toISOString();
    const seeds = [...evalWorkflowIds.map(workflow => ({ workflow, id: `builtin-${workflow}`, defaultPrompt: evalWorkflows[workflow].defaultPrompt })),
      { workflow: 'alternatives' as const, id: 'builtin-template-alternatives', defaultPrompt: templateAlternativePrompt }];
    for (const { workflow, id, defaultPrompt } of seeds) {
      const builtin = existing.find(prompt => prompt.id === id && prompt.projectId === projectId);
      if (builtin) {
        // Workflow inputs changed (e.g. Alternatives now reads an AgentContext): keep history, add a valid version.
        const latest = latestVersion(builtin);
        if (latest.format !== 'explicit-v1' || Object.values(latest.stages).some(body => /\{\{\s*passes?\s*\}\}/.test(body) || body.includes('Read few-shot.json: five synthetic')) || promptHasErrors(validatePromptStages(evalWorkflows[workflow], latest.stages)))
          await this.store.save({ ...builtin, updatedAt: now, versions: [...builtin.versions, { version: latest.version + 1, createdAt: now,
            templateBase: legacyPromptTemplateBase(defaultPrompt.stages), contentHash: promptContentHash(defaultPrompt.stages), derivation: { parent: { promptId: builtin.id, version: latest.version }, kind: 'revision' }, format: 'explicit-v1', note: 'All instructions are now explicit in the prompt; run-level task variables are removed.', stages: defaultPrompt.stages }] });
        continue;
      }
      await this.store.save({ schemaVersion: 1, id, projectId, workflow, name: defaultPrompt.name, description: defaultPrompt.description,
        builtin: true, createdAt: now, updatedAt: now, versions: [{ version: 1, templateBase: legacyPromptTemplateBase(defaultPrompt.stages), format: 'explicit-v1', createdAt: now, contentHash: promptContentHash(defaultPrompt.stages), stages: defaultPrompt.stages }] });
    }
  }
  private async seeded() {
    const projectId = await this.projectId();
    this.seeding ??= this.seed(projectId).finally(() => { this.seeding = undefined; });
    await this.seeding;
    return projectId;
  }
  async list() {
    const projectId = await this.seeded();
    return (await this.store.list()).filter(prompt => prompt.projectId === projectId)
      .sort((a, b) => Number(!!b.builtin) - Number(!!a.builtin) || a.createdAt.localeCompare(b.createdAt));
  }
  async read(id: string) {
    const projectId = await this.seeded(), prompt = await this.store.read(id);
    if (!prompt || prompt.projectId !== projectId) throw new ApplicationError('invalid-input', 'Prompt not found.');
    return prompt;
  }
  async save(raw: unknown) {
    const input = saveEvalPromptSchema.parse(raw), hash = sha256(JSON.stringify(input));
    const prior = this.saves.get(input.requestId);
    if (prior) {
      if (prior.hash !== hash) throw new ApplicationError('conflict', 'Request ID already used for another prompt save.');
      return prior.result;
    }
    const result = this.serialize(() => this.write(input));
    this.saves.set(input.requestId, { hash, result });
    result.catch(() => this.saves.delete(input.requestId));
    if (this.saves.size > 200) this.saves.delete(this.saves.keys().next().value!);
    return result;
  }
  private async write(input: ReturnType<typeof saveEvalPromptSchema.parse>) {
    const workflow = evalWorkflows[input.workflow];
    const source = input.promptId ? await this.read(input.promptId) : undefined;
    const templateBase = input.templateBase ?? (source ? latestVersion(source).templateBase ?? legacyPromptTemplateBase(latestVersion(source).stages) : defaultPromptTemplateBase);
    const tagIssues = Object.values(input.stages).flatMap(text => parsePromptSections(text, templateBase).issues);
    if (tagIssues.length) throw new ApplicationError('invalid-input', tagIssues.map(i => i.message).join(' '));
    const parents = input.parents ?? (input.derivation ? [{ ...input.derivation.parent, relation: input.derivation.kind }] : source ? [{ promptId: source.id, version: input.baseVersion!, relation: 'revision' as const }] : []);
    if (parents.some(p => p.relation === 'merge') && parents.length < 2) throw new ApplicationError('invalid-input', 'A merge requires at least two parent versions.');
    for (const parent of parents) await this.validateDerivation({ parent, kind: parent.relation }, input.workflow, input.promptId ? { promptId: input.promptId, version: input.baseVersion! + 1 } : undefined);
    if (promptHasErrors(validatePromptStages(workflow, input.stages, await this.references?.ids() ?? new Set()))) throw new ApplicationError('invalid-input', 'Fix the prompt errors before saving.');
    const now = new Date().toISOString(), stages = Object.fromEntries(workflow.stages.map(stage => [stage.id, input.stages[stage.id]]));
    if (input.derivation) await this.validateDerivation(input.derivation, input.workflow);
    if (!input.promptId) {
      const existing = await this.store.read(input.requestId);
      if (existing) {
        const first = existing.versions[0];
        if (existing.projectId !== await this.projectId() || existing.name !== input.name || existing.workflow !== input.workflow || promptContentHash(first.stages) !== promptContentHash(stages)
          || JSON.stringify(first.parents) !== JSON.stringify(parents) || JSON.stringify(first.templateBase) !== JSON.stringify(templateBase)) throw new ApplicationError('conflict', 'Request ID already used for another prompt.');
        return existing;
      }
      const prompt: EvalPrompt = { schemaVersion: 1, id: input.requestId, projectId: await this.projectId(), workflow: input.workflow, name: input.name,
        ...(input.description ? { description: input.description } : {}), createdAt: now, updatedAt: now,
        versions: [{ version: 1, templateBase, parents, format: 'explicit-v1', createdAt: now, ...(input.note ? { note: input.note } : {}), contentHash: promptContentHash(stages), ...(input.derivation ? { derivation: input.derivation } : {}), stages }] };
      await this.store.save(prompt); return prompt;
    }
    const prompt = await this.read(input.promptId), latest = latestVersion(prompt);
    if (prompt.workflow !== input.workflow) throw new ApplicationError('invalid-input', 'A prompt cannot change workflow.');
    if (latest.version !== input.baseVersion) throw new ApplicationError('conflict', `This prompt was saved as v${latest.version} since you opened it. Reload it before saving.`);
    const derivation: PromptDerivation = input.derivation ?? { parent: { promptId: prompt.id, version: latest.version }, kind: 'revision' };
    await this.validateDerivation(derivation, input.workflow, { promptId: prompt.id, version: latest.version + 1 });
    const changed = promptContentHash(latest.stages) !== promptContentHash(stages) || JSON.stringify(latest.templateBase) !== JSON.stringify(templateBase) || !!input.parents;
    const next: EvalPrompt = { ...prompt, name: input.name, updatedAt: now,
      ...(input.description !== undefined ? { description: input.description || undefined } : {}),
      versions: changed ? [...prompt.versions, { version: latest.version + 1, templateBase, parents, format: 'explicit-v1' as const, createdAt: now, ...(input.note ? { note: input.note } : {}), contentHash: promptContentHash(stages), derivation, stages }] : prompt.versions };
    await this.store.save(next); return next;
  }
  async fork(id: string, version: number, requestId: string, name: string) {
    const source = await this.read(id), pinned = source.versions.find(v => v.version === version);
    if (!pinned) throw new ApplicationError('invalid-input', 'Parent version not found.');
    return this.save({ requestId, workflow: source.workflow, name, stages: pinned.stages,
      templateBase: pinned.templateBase ?? legacyPromptTemplateBase(pinned.stages),
      derivation: { parent: { promptId: id, version }, kind: 'fork' } });
  }
  async snapshot(requestId: string, name: string) {
    if (!this.snapshots) throw Error('Snapshot storage unavailable.');
    return this.serialize(async () => {
      const projectId = await this.projectId(), existing = await this.snapshots!.read(requestId);
      if (existing) { if (existing.projectId !== projectId || existing.name !== name) throw new ApplicationError('conflict', 'Snapshot request ID already used.'); return existing; }
      const prompts = structuredClone(await this.list());
      const snapshot = { id: requestId, projectId, name, createdAt: new Date().toISOString(), prompts };
      await this.snapshots!.save(snapshot); return snapshot;
    });
  }
  async readSnapshot(id: string) {
    const snapshot = await this.snapshots?.read(id);
    if (!snapshot || snapshot.projectId !== await this.projectId()) throw new ApplicationError('invalid-input', 'Snapshot not found.');
    return snapshot;
  }
  async listSnapshots() { const projectId = await this.projectId(); return (await this.snapshots?.list() ?? []).filter(s => s.projectId === projectId); }
  setArchived(id: string, archived: boolean) {
    return this.serialize(async () => {
    const prompt = await this.read(id), next = { ...prompt, archivedAt: archived ? new Date().toISOString() : undefined };
    await this.store.save(next); return next;
    });
  }
  async resolve(promptId: string, version: number, workflow: string): Promise<EvalRunPrompt> {
    const prompt = await this.read(promptId), pinned = prompt.versions.find(item => item.version === version);
    if (prompt.workflow !== workflow) throw new ApplicationError('invalid-input', `${prompt.name} belongs to another workflow.`);
    if (!pinned) throw new ApplicationError('invalid-input', `${prompt.name} has no v${version}.`);
    // Cited reference text is frozen into the run with the prompt.
    const ids = [...new Set(Object.values(pinned.stages).flatMap(templateReferences))];
    const references = ids.length ? Object.fromEntries(await Promise.all(ids.map(async id => {
      const reference = await this.references?.read(id).catch(() => undefined);
      if (!reference) throw new ApplicationError('invalid-input', `${prompt.name} v${version} cites reference ${id}, which no longer exists.`);
      return [id, { name: reference.name, ascii: reference.ascii, ...(reference.comment ? { comment: reference.comment } : {}) }] as const;
    }))) : undefined;
    return { promptId, version, name: prompt.name, stages: pinned.stages, templateBase: pinned.templateBase ?? legacyPromptTemplateBase(pinned.stages), parents: pinned.parents, contentHash: promptContentHash(pinned.stages), ...(pinned.derivation ? { derivation: pinned.derivation } : {}), ...(references ? { references } : {}) };
  }
}

import { judgeDiagramChangeTrees } from '../../../domain/mapping/evals/diagramChangeTree';
import { saveExperimentSchema, relaunchExperimentSchema, approveExperimentSchema, judgeExperimentSchema, type EvalExperiment } from '../../../domain/mapping/evals/experiment';
import { summarizeEvalRun, type EvalRun } from '../../../domain/mapping/evals/evalRun';
import { sha256 } from '../../../domain/core/sha256';
import { ApplicationError } from '../../core/errors';
import type { EvalRunService } from './evalRunService';

export type StoredExperiment = EvalExperiment & { lastRequest: { id: string; hash: string }; startedRunIds?: string[]; preparedRuns?: EvalRun[]; approvalRequest?: { id: string; hash: string }; launches?: { id: string; hash: string; sample: EvalExperiment['samples'][number] }[] };
export interface ExperimentStore { list(): Promise<StoredExperiment[]>; read(id: string): Promise<StoredExperiment | null>; save(value: StoredExperiment): Promise<void> }
export class ExperimentService {
  private writes: Promise<unknown> = Promise.resolve();
  constructor(private store: ExperimentStore, private runs: Pick<EvalRunService, 'read' | 'judgements'> & Partial<Pick<EvalRunService, 'editedPrompt' | 'launchEdited' | 'prepareForReview' | 'launchPrepared'>>,
    private projects: { loadProject(): Promise<{ id: string } | null> },
    private contexts: { read(id: string, resolveSources: boolean): Promise<{ contentHash: string }> }) {}
  private public({ lastRequest: _, launches: __, preparedRuns: ___, approvalRequest: ____, startedRunIds: _____, ...record }: StoredExperiment): EvalExperiment { return structuredClone(record); }
  private async projectId() {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Open a project first.');
    return project.id;
  }
  async list() {
    const projectId = await this.projectId();
    return (await this.store.list()).filter(e => e.projectId === projectId).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).map(e => this.public(e));
  }
  async read(id: string) {
    const item = await this.store.read(id);
    if (!item || item.projectId !== await this.projectId()) throw new ApplicationError('invalid-input', 'Experiment not found.');
    return this.public(item);
  }
  save(raw: unknown) {
    const input = saveExperimentSchema.parse(raw), hash = sha256(JSON.stringify(input));
    const work = async () => {
      const projectId = await this.projectId(), id = input.experimentId ?? input.requestId;
      const previous = await this.store.read(id);
      if (previous && previous.projectId !== projectId) throw new ApplicationError('invalid-input', 'Experiment not found.');
      if (previous?.lastRequest.id === input.requestId) {
        if (previous.lastRequest.hash !== hash) throw new ApplicationError('conflict', 'Request ID already used for different content.');
        return this.public(previous);
      }
      if (input.experimentId ? !previous || previous.revision !== input.expectedRevision : !!previous)
        throw new ApplicationError('conflict', 'Experiment changed. Read its current revision before updating.');
      const design = input.experiment;
      for (const inputCase of design.cases) {
        const context = await this.contexts.read(inputCase.agentContextId, false);
        if (inputCase.contentHash && inputCase.contentHash !== context.contentHash)
          throw new ApplicationError('invalid-input', 'Input case hash does not match its saved AgentContext.');
      }
      const runIds = [...new Set(design.samples.flatMap(s => s.outputs.map(o => o.runId)))];
      const runs = await Promise.all(runIds.map(id => this.runs.read(id)));
      for (const sample of design.samples) for (const output of sample.outputs) {
        const run = runs.find(r => r.id === output.runId)!;
        const inputCase = design.cases.find(c => c.id === sample.caseId)!;
        if (run.projectId !== projectId || run.agentContextId !== inputCase.agentContextId || !run.cells.some(c => c.key === output.cellKey))
          throw new ApplicationError('invalid-input', 'Stage output must reference an existing run cell for its input case and project.');
        if (inputCase.contentHash && !Object.values(run.contexts ?? {}).some(c => c.agentContextId === inputCase.agentContextId && c.contentHash === inputCase.contentHash))
          throw new ApplicationError('invalid-input', 'Stage output context does not match the pinned input hash.');
      }
      const judgements = await this.runs.judgements?.list() ?? [];
      const otherExperiments = (await this.store.list()).filter(e => e.projectId === projectId && e.id !== id);
      for (const comparison of design.comparisons) for (const judgementId of comparison.judgementIds) {
        const judgement = judgements.find(j => j.id === judgementId);
        const outputs = design.samples.filter(s => s.phaseId === comparison.phaseId && comparison.caseIds.includes(s.caseId) && comparison.conditionIds.includes(s.conditionId)).flatMap(s => s.outputs);
        if (!judgement || judgement.projectId !== projectId || !judgement.subjects.length || judgement.subjects.some(subject => !outputs.some(o => o.runId === subject.runId && o.cellKey === subject.outputKey)))
          throw new ApplicationError('invalid-input', 'Judgement subjects must belong to this comparison’s phase, cases and conditions.');
        if (otherExperiments.some(e => e.comparisons.some(c => c.judgementIds.includes(judgementId))))
          throw new ApplicationError('conflict', 'This Judgement already has a home in another experiment.');
      }
      const samePlan = JSON.stringify(previous?.plannedRuns) === JSON.stringify(design.plannedRuns)
        && JSON.stringify(previous?.cases) === JSON.stringify(design.cases);
      const startedRunIds = previous?.startedRunIds ?? (previous?.generationReview?.status === 'started' ? previous.plannedRuns?.map(p => p.request.requestId) ?? [] : []);
      if (previous?.generationReview?.status === 'starting' && !samePlan)
        throw new ApplicationError('conflict', 'Finish the recorded generation approval before changing the plan.');
      for (const old of previous?.plannedRuns ?? []) if (startedRunIds.includes(old.request.requestId)) {
        if (JSON.stringify(design.plannedRuns?.find(p => p.request.requestId === old.request.requestId)) !== JSON.stringify(old))
          throw new ApplicationError('conflict', 'An approved generation plan cannot be changed. Add a new phase instead.');
        for (const output of old.outputs) {
          const before = previous!.samples.find(s => s.id === output.sampleId)!;
          const after = design.samples.find(s => s.id === before.id);
          // Introducing phases may label the original round without changing its approved execution.
          const comparable = after && !previous!.phases?.length && !before.phaseId
            ? (({ phaseId: _, ...sample }) => sample)(after) : after;
          if (JSON.stringify(comparable) !== JSON.stringify(before) || JSON.stringify(design.cases.find(c => c.id === before.caseId)) !== JSON.stringify(previous!.cases.find(c => c.id === before.caseId)))
            throw new ApplicationError('conflict', 'Approved samples and inputs cannot be reassigned.');
        }
      }
      let preparedRuns = samePlan ? previous?.preparedRuns : undefined;
      if (design.plannedRuns?.length && !preparedRuns) {
        if (!this.runs.prepareForReview) throw Error('Generation review is unavailable.');
        preparedRuns = [];
        for (const plan of design.plannedRuns) {
          const alreadyStarted = startedRunIds.includes(plan.request.requestId);
          const run = alreadyStarted ? previous!.preparedRuns!.find(r => r.id === plan.request.requestId)! : await this.runs.prepareForReview(plan.request);
          if (run.projectId !== projectId) throw Error('Planned run belongs to another project.');
          if (run.cells.length !== plan.outputs.length || new Set(plan.outputs.map(o => o.cellKey)).size !== run.cells.length) throw Error('Map every planned generation cell exactly once.');
          for (const output of plan.outputs) {
            const sample = design.samples.find(s => s.id === output.sampleId)!;
            const inputCase = design.cases.find(c => c.id === sample.caseId)!;
            if (!run.cells.some(c => c.key === output.cellKey) || run.agentContextId !== inputCase.agentContextId
              || inputCase.contentHash && !Object.values(run.contexts ?? {}).some(c => c.contentHash === inputCase.contentHash)) throw Error('Planned output does not match its case and cell.');
            if (!alreadyStarted && sample.outputs.some(o => o.stageId === output.stageId)) throw Error('Planned stage already has an output.');
          }
          preparedRuns.push(run);
        }
      }
      for (const plan of design.plannedRuns ?? []) for (const output of plan.outputs) {
        const sample = design.samples.find(s => s.id === output.sampleId)!;
        const inputCase = design.cases.find(c => c.id === sample.caseId)!;
        const run = preparedRuns!.find(r => r.id === plan.request.requestId)!;
        if (run.agentContextId !== inputCase.agentContextId) throw Error('Planned sample input cannot be reassigned.');
        if (!startedRunIds.includes(plan.request.requestId) && sample.outputs.some(o => o.stageId === output.stageId)) throw Error('Planned stage already has an output.');
      }
      const generationReview = preparedRuns?.length ? samePlan && previous?.generationReview
        ? previous.generationReview : { status: 'awaiting-approval' as const, runs: preparedRuns.filter(r => !startedRunIds.includes(r.id)).map(summarizeEvalRun) } : undefined;
      const now = new Date().toISOString();
      const saved: StoredExperiment = { ...design, startedRunIds, ...(preparedRuns ? { preparedRuns, generationReview } : {}), ...(samePlan && previous?.approvalRequest ? { approvalRequest: previous.approvalRequest } : {}), ...(previous?.launches ? { launches: previous.launches } : {}), schemaVersion: 1, id, projectId, revision: (previous?.revision ?? 0) + 1, createdAt: previous?.createdAt ?? now, updatedAt: now, lastRequest: { id: input.requestId, hash } };
      await this.store.save(saved); return this.public(saved);
    };
    const pending = this.writes.then(work); this.writes = pending.catch(() => {}); return pending;
  }
  approve(id: string, raw: unknown) {
    const input = approveExperimentSchema.parse(raw), hash = sha256(JSON.stringify(input));
    const work = async () => {
      await this.read(id);
      const experiment = (await this.store.read(id))!;
      const receipt = experiment.approvalRequest;
      if (receipt && (receipt.id !== input.requestId || receipt.hash !== hash)) throw new ApplicationError('conflict', 'Generation approval already recorded. Refresh the experiment.');
      if (!receipt && experiment.revision !== input.expectedRevision) throw new ApplicationError('conflict', 'Experiment changed. Review its current prompts before approving.');
      if (!experiment.preparedRuns?.length || !experiment.generationReview || !this.runs.launchPrepared) throw Error('No generation plan to approve.');
      if (experiment.generationReview.status === 'started') return this.public(experiment);
      if (!receipt) {
        experiment.approvalRequest = { id: input.requestId, hash };
        experiment.generationReview.approval = input;
        experiment.generationReview.status = 'starting'; experiment.generationReview.approvedAt = new Date().toISOString();
        experiment.revision++; experiment.updatedAt = new Date().toISOString();
        await this.store.save(experiment);
      }
      for (const run of experiment.preparedRuns) if (!(experiment.startedRunIds ?? []).includes(run.id)) {
        await this.runs.launchPrepared(run);
        (experiment.startedRunIds ??= []).push(run.id);
        await this.store.save(experiment);
      }
      for (const plan of experiment.plannedRuns ?? []) for (const output of plan.outputs) {
        const sample = experiment.samples.find(s => s.id === output.sampleId)!;
        if (!sample.outputs.some(o => o.stageId === output.stageId)) sample.outputs.push({ stageId: output.stageId, runId: plan.request.requestId, cellKey: output.cellKey });
      }
      experiment.generationReview.status = 'started'; experiment.revision++; experiment.updatedAt = new Date().toISOString();
      await this.store.save(experiment); return this.public(experiment);
    };
    const pending = this.writes.then(work); this.writes = pending.catch(() => {}); return pending;
  }
  judge(id: string, raw: unknown) {
    const input = judgeExperimentSchema.parse(raw), fingerprint = sha256(JSON.stringify({ experimentId: id, ...input }));
    const work = async () => {
      await this.read(id);
      const experiment = (await this.store.read(id))!;
      const comparison = experiment.comparisons.find(c => c.id === input.comparisonId);
      if (!comparison?.evaluator || !this.runs.judgements) throw new ApplicationError('invalid-input', 'Choose a deterministic phase assessment.');
      if (comparison.judgementIds.includes(input.requestId)) {
        const previous = await this.runs.judgements.read(input.requestId);
        if (previous.source.fingerprint !== fingerprint) throw new ApplicationError('conflict', 'Judgement request ID already used.');
        return this.public(experiment);
      }
      if (experiment.revision !== input.expectedRevision) throw new ApplicationError('conflict', 'Experiment changed. Refresh before judging.');
      const samples = experiment.samples.filter(s => s.phaseId === comparison.phaseId && comparison.caseIds.includes(s.caseId) && comparison.conditionIds.includes(s.conditionId));
      if (!samples.length || samples.some(s => !s.outputs.length || !s.relaunchedFrom && s.outputs.length !== experiment.workflow.stages.length))
        throw new ApplicationError('invalid-input', 'Generate all phase outputs before running this assessment.');
      const outputs = samples.flatMap(s => s.outputs);
      const runs = await Promise.all([...new Set(outputs.map(o => o.runId))].map(id => this.runs.read(id)));
      const evidence = outputs.map(output => {
        const run = runs.find(r => r.id === output.runId)!;
        const cell = run.cells.find(c => c.key === output.cellKey);
        if (run.projectId !== experiment.projectId || !cell || cell.status !== 'finished' || cell.proposalTree === undefined || !cell.canvasId || !cell.checkpointId)
          throw new ApplicationError('invalid-input', 'Every assessed output must be a finished diagram-change proposal.');
        return { runId: run.id, outputKey: cell.key, text: cell.proposalTree, source: { documentId: cell.canvasId, checkpointId: cell.checkpointId } };
      });
      const now = new Date().toISOString();
      await this.runs.judgements.saveDeterministic({ schemaVersion: 1, id: input.requestId, projectId: experiment.projectId,
        title: `${experiment.phases?.find(p => p.id === comparison.phaseId)?.name ?? experiment.name} · ${comparison.name}`,
        createdAt: now, updatedAt: now, runIds: runs.map(r => r.id), subjects: evidence.map(({ text: _, ...subject }) => subject),
        evaluator: comparison.evaluator, kind: 'diagram-change-tree', status: 'finished', canvases: [],
        source: { kind: 'experiment', id, fingerprint }, data: judgeDiagramChangeTrees(evidence.map(({ source: _, ...item }) => item)) });
      comparison.judgementIds.push(input.requestId); experiment.revision++; experiment.updatedAt = now;
      await this.store.save(experiment);
      return this.public(experiment);
    };
    const pending = this.writes.then(work); this.writes = pending.catch(() => {}); return pending;
  }
  relaunch(id: string, raw: unknown) {
    const input = relaunchExperimentSchema.parse(raw), hash = sha256(JSON.stringify(input));
    const work = async () => {
      await this.read(id);
      const experiment = (await this.store.read(id))!;
      let receipt = experiment.launches?.find(l => l.id === input.requestId);
      if (receipt && receipt.hash !== hash) throw new ApplicationError('conflict', 'Relaunch request ID already used for different edits.');
      if (receipt && experiment.samples.some(s => s.id === receipt!.sample.id)) return { experiment: this.public(experiment), runId: input.requestId };
      if (!receipt && input.expectedRevision !== experiment.revision) throw new ApplicationError('conflict', 'Experiment changed. Refresh before relaunching.');
      const sample = experiment.samples.find(s => s.id === input.sampleId), output = sample?.outputs.find(o => o.stageId === input.stageId);
      if (!sample || !output || !this.runs.launchEdited || !this.runs.editedPrompt) throw new ApplicationError('invalid-input', 'Choose an existing generation output to relaunch.');
      const source = await this.runs.read(output.runId);
      await this.runs.editedPrompt(source, output.cellKey, input.stages);
      if (!receipt) {
        const attempts = [...experiment.samples, ...(experiment.launches ?? []).map(l => l.sample)].filter(s => s.phaseId === sample.phaseId && s.caseId === sample.caseId && s.conditionId === sample.conditionId && s.number === sample.number);
        receipt = { id: input.requestId, hash, sample: { id: `attempt-${input.requestId}`, ...(sample.phaseId ? { phaseId: sample.phaseId } : {}), caseId: sample.caseId, conditionId: sample.conditionId, number: sample.number,
          attempt: Math.max(...attempts.map(s => s.attempt)) + 1, relaunchedFrom: { sampleId: sample.id, stageId: input.stageId }, outputs: [] } };
        experiment.launches = [...experiment.launches ?? [], receipt];
        await this.store.save(experiment);
      }
      const run = await this.runs.launchEdited(source.id, output.cellKey, input.stages, input.requestId);
      const selected = source.cells.find(c => c.key === output.cellKey)!;
      const outputs = sample.outputs.filter(o => o.runId === source.id).flatMap(o => {
        const before = source.cells.find(c => c.key === o.cellKey);
        if (!before || before.promptId !== selected.promptId || source.workflow !== 'few-shot-refinement' && before.pass !== selected.pass) return [];
        const cell = run.cells.find(c => c.stage === before.stage && c.pass === (source.workflow === 'few-shot-refinement' ? before.pass : 1));
        if (!cell) throw Error('Relaunched workflow did not produce the expected stage cell.');
        return [{ stageId: o.stageId, runId: run.id, cellKey: cell.key }];
      });
      experiment.samples.push({ ...receipt.sample, outputs }); experiment.revision++; experiment.updatedAt = new Date().toISOString();
      await this.store.save(experiment);
      return { experiment: this.public(experiment), runId: run.id };
    };
    const pending = this.writes.then(work); this.writes = pending.catch(() => {}); return pending;
  }
}

import { fewShotProgressSchema } from '../../../domain/mapping/evals/fewShot';
import { diagramChangeTreeResultSchema } from '../../../domain/mapping/evals/diagramChangeTree';
import { ApplicationError } from '../../core/errors';
import type { ComparisonRun } from '../../../domain/mapping/compare/comparisonGeneration';
import type { ComparePageSession, CompareCanvasCopy } from '../../../domain/mapping/compare/comparePageSession';
import { canvasJudgementSchema, diagramJudgementSchema, summarizeJudgement, type Judgement, type JudgementSubject } from '../../../domain/mapping/evals/judgement';
import type { CompareSessionService } from '../compare/compareSessionService';
import type { ComparisonGenerationService, ComparisonRunStore } from '../compare/comparisonGenerationService';
import type { EvalRunStore } from './evalRunService';

export interface JudgementStore { list(): Promise<Judgement[]>; read(id: string): Promise<Judgement | null>; save(value: Judgement): Promise<void> }

/** Imports existing comparisons and materializes new evaluator results as independently typed records. */
export class JudgementService {
  private queue = Promise.resolve();
  constructor(private store: JudgementStore, private sessions: CompareSessionService, private comparisonStore: ComparisonRunStore,
    private comparisons: ComparisonGenerationService, private runs: EvalRunStore) {
    this.queue = store.list().then(async records => {
      for (const item of records) if (item.source.kind === 'eval-run' && !item.deletedAt && ['queued', 'generating'].includes(item.status))
        await store.save({ ...item, status: 'failed', error: 'Server restarted during evaluation. Completed rounds are retained.', updatedAt: new Date().toISOString() });
    });
  }
  private serialize<T>(task: () => Promise<T>): Promise<T> {
    const pending = this.queue.then(task); this.queue = pending.then(() => {}, () => {}); return pending;
  }
  private async reconcile() {
    const [sessions, jobs, existing, runs] = await Promise.all([this.sessions.list(), this.comparisonStore.list(), this.store.list(), this.runs.list()]);
    const records = new Map(existing.map(item => [item.id, item]));
    const jobsById = new Map(jobs.map(job => [job.sessionId ?? job.id, job]));
    const sources = new Set([...sessions.map(item => item.id), ...jobs.map(item => item.id)]);
    const subjects = (canvases: CompareCanvasCopy[]): JudgementSubject[] => canvases.map(copy => {
      const owner = runs.find(run => run.id === copy.generated?.runId) ?? runs.find(run => run.cells.some(cell => cell.canvasId === copy.source.documentId));
      const runId = owner?.id ?? copy.generated?.runId;
      const outputKey = owner?.cells.find(cell => cell.canvasId === copy.source.documentId)?.key;
      return { source: copy.source, ...(runId ? { runId } : {}), ...(outputKey ? { outputKey } : {}) };
    });
    const fingerprint = (job?: ComparisonRun) => JSON.stringify(job ? [job.status, job.completedAt, job.error, job.sessionId] : ['manual']);
    const save = async (sourceId: string, session: ComparePageSession | undefined, job: ComparisonRun | undefined) => {
      const canvases = session?.canvases ?? job!.canvases, refs = subjects(canvases);
      const common = { schemaVersion: 1 as const, projectId: session?.projectId ?? job!.projectId,
        title: session?.title ?? job!.request.title, createdAt: job?.createdAt ?? session!.createdAt, updatedAt: job?.completedAt ?? session?.createdAt ?? job!.createdAt,
        subjects: refs, runIds: [...new Set(refs.flatMap(ref => ref.runId ? [ref.runId] : []))], canvases,
        evaluator: job ? { kind: 'model' as const, model: job.request.model, effort: job.request.effort,
          ...(job.evaluationPrompt ? { prompt: job.evaluationPrompt, promptVersion: job.evaluationPromptVersion ?? 1 } : {}) } : { kind: 'manual' as const },
        status: session ? 'finished' as const : job!.status === 'finished' ? 'failed' as const : job!.status,
        error: !session && job?.status === 'finished' ? 'The saved comparison result is unavailable.' : job?.error, usage: job?.usage,
        source: { kind: 'comparison' as const, id: sourceId, fingerprint: fingerprint(job) } };
      const diagrams = session?.compares.filter(pair => pair.A.kind === 'diagram' && pair.B.kind === 'diagram') ?? [];
      const canvasesCompared = session?.compares.filter(pair => pair.A.kind !== 'diagram' && pair.B.kind !== 'diagram') ?? [];
      const results: Judgement[] = [];
      if (job?.request.experiment) results.push({ ...common, id: `${sourceId}-report`, kind: 'comparison-report', status: job.status, error: job.error, ...(job.report ? { data: job.report } : {}) });
      if (diagrams.length || !session && job && !job.request.experiment) results.push({ ...common, id: `${sourceId}-diagram`, kind: 'diagram-comparison',
        ...(diagrams.length ? { data: diagramJudgementSchema.parse({ comparisons: diagrams }) } : {}) });
      if (canvasesCompared.length) results.push({ ...common, id: `${sourceId}-canvas`, kind: 'canvas-comparison', data: canvasJudgementSchema.parse({
        comparisons: canvasesCompared.map(pair => ({ ...pair, A: { ...pair.A, kind: 'canvas' }, B: { ...pair.B, kind: 'canvas' } }))
      }) });
      for (const result of results) {
        if (result.data && result.kind !== 'few-shot-progress' && result.kind !== 'comparison-report' && result.kind !== 'diagram-change-tree') {
          const used = new Set(result.data.comparisons.flatMap(pair => [pair.A.canvasCopyId, pair.B.canvasCopyId]));
          result.canvases = canvases.filter(copy => used.has(copy.id));
          result.subjects = subjects(result.canvases);
          result.runIds = [...new Set(result.subjects.flatMap(ref => ref.runId ? [ref.runId] : []))];
        }
        const previous = records.get(result.id);
        if (previous?.deletedAt) continue;
        if (!previous || previous.status !== result.status || previous.source.fingerprint !== result.source.fingerprint || JSON.stringify(previous.subjects) !== JSON.stringify(result.subjects)) await this.store.save(result);
      }
    };
    for (const summary of sessions) {
      const job = jobsById.get(summary.id);
      // Completed session snapshots never change; avoid loading them again during polling.
      const previous = existing.filter(item => item.source.id === summary.id);
      if (previous.length && previous.every(item => item.deletedAt || item.status === 'finished' && item.source.fingerprint === fingerprint(job) && item.subjects.every(ref => ref.runId))) continue;
      await save(summary.id, await this.sessions.read(summary.id), job);
    }
    for (const job of jobs) if (!sessions.some(session => session.id === (job.sessionId ?? job.id))) await save(job.id, undefined, job);
    // Deletion through legacy comparison APIs also removes its imported judgements.
    for (const item of existing) if (item.source.kind === 'comparison' && !item.deletedAt && !sources.has(item.source.id)) await this.store.save({ ...item, deletedAt: new Date().toISOString() });
  }
  /** Native workflow results share the same durable store, without legacy import ownership. */
  saveDeterministic(item: Extract<Judgement, { kind: 'diagram-change-tree' }>) {
    return this.serialize(async () => {
      const previous = await this.store.read(item.id);
      if (previous) {
        if (previous.deletedAt || previous.source.fingerprint !== item.source.fingerprint) throw new ApplicationError('conflict', 'Judgement request ID already used.');
        return previous;
      }
      diagramChangeTreeResultSchema.parse(item.data);
      await this.store.save(structuredClone(item));
      return item;
    });
  }
  saveProgress(item: Extract<Judgement, { kind: 'few-shot-progress' }>) {
    return this.serialize(async () => {
      const previous = await this.store.read(item.id);
      if (previous?.deletedAt) return;
      if (item.data) fewShotProgressSchema.parse(item.data);
      await this.store.save(structuredClone(item));
    });
  }
  async list(runId?: string) {
    return this.serialize(async () => {
      await this.reconcile();
      return (await this.store.list()).filter(item => !item.deletedAt && (!runId || item.runIds.includes(runId)))
        .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id)).map(summarizeJudgement);
    });
  }
  async read(id: string) {
    return this.serialize(async () => {
      await this.reconcile();
      const item = await this.store.read(id);
      if (!item || item.deletedAt) throw new ApplicationError('invalid-input', 'Judgement not found.');
      return item;
    });
  }
  async delete(id: string) {
    return this.serialize(async () => {
      await this.reconcile();
      const item = await this.store.read(id);
      if (!item || item.deletedAt) return;
      await this.store.save({ ...item, deletedAt: new Date().toISOString() });
      if (item.source.kind === 'comparison' && (item.status === 'queued' || item.status === 'generating')) await this.comparisons.delete(item.source.id);
    });
  }
}

